"use client";

/**
 * Web Audio plumbing shared by every VoiceBeam instance.
 *
 * One AudioContext for the page, one MediaStreamAudioSourceNode per stream
 * (reference-counted, so several beams can listen to the same microphone),
 * and one AnalyserNode per instance. Nothing is connected to the
 * destination, so the audio is analysed but never played back.
 */

let context: AudioContext | null = null;

type AudioContextCtor = typeof AudioContext;

function resolveAudioContext(): AudioContextCtor | null {
  if (typeof window === 'undefined') return null;
  const w = window as unknown as { AudioContext?: AudioContextCtor; webkitAudioContext?: AudioContextCtor };
  return w.AudioContext ?? w.webkitAudioContext ?? null;
}

/** True when this browser can analyse audio at all. */
export function isAudioSupported(): boolean {
  return resolveAudioContext() != null;
}

/**
 * The page's shared AudioContext, created on first use. Call it from a
 * user gesture (the microphone button) where you can: Safari only lets a
 * context start inside one. It is resumed on every call, so a context the
 * browser suspended in the background picks up again.
 */
export function getAudioContext(): AudioContext | null {
  const Ctor = resolveAudioContext();
  if (!Ctor) return null;
  if (!context) context = new Ctor();
  if (context.state === 'suspended') {
    context.resume().catch(() => {
      /* A resume outside a gesture may be refused; the next gesture retries. */
    });
  }
  return context;
}

interface SharedSource {
  node: MediaStreamAudioSourceNode;
  refs: number;
}

const sources = new WeakMap<MediaStream, SharedSource>();

export interface AnalyserLease {
  analyser: AnalyserNode;
  release: () => void;
}

/**
 * An AnalyserNode fed by `stream`, plus the function that tears it down.
 * Returns null when the browser has no Web Audio or the stream carries no
 * audio track.
 */
export function acquireAnalyser(stream: MediaStream): AnalyserLease | null {
  const ctx = getAudioContext();
  if (!ctx) return null;
  if (stream.getAudioTracks().length === 0) return null;

  let shared = sources.get(stream);
  if (!shared) {
    shared = { node: ctx.createMediaStreamSource(stream), refs: 0 };
    sources.set(stream, shared);
  }
  shared.refs += 1;

  const analyser = ctx.createAnalyser();
  // 1024 bins at 48 kHz is ~47 Hz per bin: fine enough to split the voice
  // bands, cheap enough to read every frame.
  analyser.fftSize = 1024;
  // The driver does its own attack/release, so the analyser's smoothing
  // stays light — just enough to take the flicker off the spectrum.
  analyser.smoothingTimeConstant = 0.5;
  shared.node.connect(analyser);

  let released = false;
  return {
    analyser,
    release: () => {
      if (released) return;
      released = true;
      try {
        shared!.node.disconnect(analyser);
      } catch {
        /* already gone */
      }
      shared!.refs -= 1;
      if (shared!.refs <= 0) {
        try {
          shared!.node.disconnect();
        } catch {
          /* already gone */
        }
        sources.delete(stream);
      }
    },
  };
}

/**
 * Colour parsing for the palette and band props: `#rgb`, `#rrggbb`,
 * `rgb(r, g, b)` and `rgba(r, g, b, a)` all resolve to an [r, g, b]
 * triple. Anything else returns null and the caller keeps its default.
 */
export function parseRgb(color: string): [number, number, number] | null {
  const c = color.trim();
  const hex = c.match(/^#([0-9a-f]{3}|[0-9a-f]{6})$/i);
  if (hex) {
    const h = hex[1].length === 3 ? hex[1].split('').map((ch) => ch + ch).join('') : hex[1];
    return [parseInt(h.slice(0, 2), 16), parseInt(h.slice(2, 4), 16), parseInt(h.slice(4, 6), 16)];
  }
  const fn = c.match(/^rgba?\(\s*([\d.]+)\s*,\s*([\d.]+)\s*,\s*([\d.]+)/i);
  if (fn) return [Math.round(+fn[1]), Math.round(+fn[2]), Math.round(+fn[3])];
  return null;
}

/** `rgb(r, g, b)` for the stylesheet, or null if unparseable. */
export function toRgb(color: string): string | null {
  const t = parseRgb(color);
  return t ? `rgb(${t[0]}, ${t[1]}, ${t[2]})` : null;
}

/** `r, g, b` for the canvas (dropped into rgba()), or null. */
export function toTriple(color: string): string | null {
  const t = parseRgb(color);
  return t ? `${t[0]}, ${t[1]}, ${t[2]}` : null;
}

/* Build-time switch for the surface looks (`look="dots"` / `"lines"`).
   Off in the default build — npm and the libraries.dev site — so the looks
   are compiled out until they ship; `VOICE_SURFACE=1 npm run build:voice`
   turns them on for local work (see vite.config.ts and LOOKS.md). */
declare const __VOICE_SURFACE__: boolean;

export { VoiceBeam } from './VoiceBeam';
export { default } from './VoiceBeam';

/** Whether this build carries the surface looks (`look="dots"` / `"lines"`) — not released yet. */
export const VOICE_SURFACE_LOOKS: boolean = false;

export { useMicrophone } from './useMicrophone';
export type { UseMicrophoneOptions, UseMicrophoneResult, MicrophoneState } from './useMicrophone';

export { getAudioContext, isAudioSupported } from './audio';
export { parseRgb } from './color';

export { voiceDefaults, voiceTypePresets, voiceTypeStyle, resolveVoiceDefaults, resolveVoiceStyle } from './presets';
export type { VoiceGeometry, VoiceTypeStyle } from './presets';

export type {
  VoiceBeamProps,
  VoiceBeamType,
  VoiceBeamTheme,
  VoiceBeamLook,
  VoiceBeamDotShape,
  VoiceBeamLinePattern,
  VoiceBeamColorVariant,
  VoiceBeamLevel,
  VoiceBeamMotion,
  VoiceThemeColors,
} from './types';

export { themePresets, voicePalettes, voiceLobes, LOBE_SPACING, LOBE_SPAN } from './styles';
export type { VoiceLobe } from './styles';

import type { VoiceBeamType } from './types';

/**
 * The geometry and response knobs a `type` preset may retune. Everything
 * here is a prop on the component; the preset only supplies the default,
 * so an explicit prop always wins.
 */
export interface VoiceGeometry {
  /** Size of the whole effect (see the `scale` prop). */
  scale: number;
  /** Bloom blur multiplier (see the `glowSize` prop). */
  glowSize: number;
  /** Per-layer opacity multipliers on the theme preset. */
  strokeOpacity: number;
  innerOpacity: number;
  bloomOpacity: number;
  idle: number;
  reach: number;
  spread: number;
  flow: number;
  bend: number;
  bandStrength: number;
  bandWidth: number;
  bandPosition: number;
  bandCurve: number;
  bandSpread: number;
  bandSkew: number;
  bandOffset: number;
  /** How far the band's ends rise again toward the corners, as a fraction of its peak. */
  bandTail: number;
  /** Where the tail's rise starts, as a share of the centre-to-edge distance; it always reaches full lift at the corner. */
  bandTailPosition: number;
  /** Exponent of the rise: 1 a straight ramp, higher a hook that stays low then whips up at the corner. */
  bandTailCurve: number;
  /** Px the band runs past each side of the element, so the hook is cropped by the component. */
  bandTailOverflow: number;
  bandAberration: number;
  distortion: number;
  distortionDetail: number;
  glowWidth: number;
  glowHeight: number;
  lobeSpacing: number;
  rangeWidth: number;
  rangeHeight: number;
  softness: number;
  coreSize: number;
  /** The epicentre: a white wash under the band line at the centre of the edge, 0–1 (light theme only by default). */
  coreLight: number;
  coreLightWidth: number;
  coreLightHeight: number;
  strokeScale: number;
  innerScale: number;
  innerHeight: number;
  bloomScale: number;
  bloomHeight: number;
}

/**
 * The tuned defaults — the `default` type, a ~350px chat input.
 */
export const voiceDefaults: VoiceGeometry = {
  scale: 1,
  glowSize: 1,
  strokeOpacity: 1,
  innerOpacity: 1,
  bloomOpacity: 1,
  idle: 0.18,
  reach: 1.2,
  spread: 1.05,
  flow: 48,
  bend: 60,
  bandStrength: 1.55,
  bandWidth: 2.15,
  bandPosition: 0.35,
  bandCurve: 1.75,
  bandSpread: 0.87,
  bandSkew: 0.12,
  bandOffset: -27,
  bandTail: 0.59,
  bandTailPosition: 0.67,
  bandTailCurve: 2.4,
  bandTailOverflow: 15,
  bandAberration: 0.89,
  distortion: 0.62,
  distortionDetail: 2.3,
  glowWidth: 0.65,
  glowHeight: 1.25,
  lobeSpacing: 0.85,
  rangeWidth: 0.75,
  rangeHeight: 1,
  softness: 1.07,
  coreSize: 1,
  coreLight: 0,
  coreLightWidth: 1,
  coreLightHeight: 1,
  strokeScale: 1,
  innerScale: 1,
  innerHeight: 1,
  bloomScale: 1,
  bloomHeight: 1,
};

/**
 * Per-type overrides on the defaults. The glow is authored in px for the
 * default host, so a smaller or larger host needs its lobes, range and
 * band rescaled to read the same.
 *
 * - `pill`: a ~150×44 recording pill — everything pulled in, a lower
 *   reach, a shallower bend, a thinner band.
 * - `mobile`: the bottom of a phone screen (~400px wide, tall) — a wider
 *   range and lobe ring, a taller rise, a broader band.
 */
export const voiceTypePresets: Record<VoiceBeamType, Partial<VoiceGeometry>> = {
  default: {},
  pill: {
    scale: 0.45,
    glowSize: 0.95,
    strokeOpacity: 1.2,
    innerOpacity: 0.85,
    reach: 1.35,
    spread: 1.1,
    flow: 0,
    bend: 23,
    bandStrength: 1.55,
    bandWidth: 1.85,
    bandCurve: 1.95,
    bandSpread: 0.38,
    bandOffset: -16,
    bandTail: 0,
    distortion: 0.45,
    distortionDetail: 3,
    glowWidth: 0.65,
    glowHeight: 0.95,
    lobeSpacing: 0.45,
    rangeWidth: 0.8,
    rangeHeight: 0.7,
    softness: 0.88,
    coreSize: 0.25,
    strokeScale: 1.25,
    innerScale: 0.95,
    bloomScale: 1.05,
    bloomHeight: 2.25,
  },
  mobile: {
    scale: 1.25,
    spread: 0.45,
    reach: 3,
    flow: 60,
    bend: 70,
    bandWidth: 2.4,
    bandCurve: 1.55,
    bandSpread: 0.9,
    bandOffset: -50,
    bandTail: 0.62,
    bandTailPosition: 0.42,
    bandTailCurve: 2.7,
    bandTailOverflow: 22,
    bandStrength: 1.8,
    distortionDetail: 2,
    glowWidth: 1.15,
    glowHeight: 2.1,
    lobeSpacing: 1.35,
    rangeWidth: 1.25,
    rangeHeight: 1.2,
    softness: 1.1,
  },
};

/**
 * Colour tuning a type may carry on top of the theme preset (brightness
 * and saturation default per theme, so these are optional overrides).
 */
export type VoiceTypeStyle = { brightness?: number; saturation?: number; strength?: number };

export const voiceTypeStyle: Record<VoiceBeamType, VoiceTypeStyle> = {
  // The chat input sits on a dark card, so it runs a touch brighter than
  // the theme's 1.1 (light keeps the theme's own, see below).
  default: { brightness: 1.15 },
  pill: { brightness: 1.35, saturation: 1.5 },
  // The phone screen is large and the glow sits far from the content, so
  // it carries full strength on either theme (light otherwise dims to 0.8)
  // and, on dark, a brighter and richer glow than the theme's 1.1 / 1.2.
  mobile: { strength: 1, brightness: 1.2, saturation: 1.5 },
};

/**
 * What a type changes about the style on the light theme. The pill's lift
 * exists to carry the glow on a dark chip; on light it would read hotter
 * than the chat input, so the pill drops it and takes the theme's own.
 */
const voiceTypeStyleLight: Partial<Record<VoiceBeamType, VoiceTypeStyle>> = {
  default: {},
  pill: {},
  mobile: { strength: 1 },
};

/** The colour tuning for a type on a theme. */
export function resolveVoiceStyle(
  type: VoiceBeamType = 'default',
  theme: 'dark' | 'light' = 'dark'
): VoiceTypeStyle {
  const light = theme === 'light' ? voiceTypeStyleLight[type] : undefined;
  return light ?? voiceTypeStyle[type];
}

/**
 * The full geometry for a type: the defaults with the type's overrides —
 * and, for what the type leaves alone, the theme's own (the light chat
 * input carries a band strength, reach and spread of its own).
 */
/** What the light theme changes per type, on top of the type's preset. */
const lightTypeOverrides: Partial<Record<VoiceBeamType, Partial<VoiceGeometry>>> = {
  // The band on white, whatever the dark strengths: 1.7 for the chat
  // input and the phone, 2 for the pill.
  default: { bandStrength: 1.7 },
  pill: { bandStrength: 2 },
  mobile: { bandStrength: 1.7 },
};

export function resolveVoiceDefaults(type: VoiceBeamType = 'default', theme: 'dark' | 'light' = 'dark'): VoiceGeometry {
  const typePreset = voiceTypePresets[type];
  const themeOverrides: Partial<VoiceGeometry> = {};
  if (theme === 'light') {
    // The light card was tuned taller and narrower than the dark one.
    if (typePreset.reach === undefined) themeOverrides.reach = 1.8;
    if (typePreset.spread === undefined) themeOverrides.spread = 0.8;
    // On white the epicentre reads lighter than the band; dark keeps it off.
    if (typePreset.coreLight === undefined) themeOverrides.coreLight = 1.8;
  }
  return { ...voiceDefaults, ...themeOverrides, ...typePreset, ...(theme === 'light' ? lightTypeOverrides[type] : undefined) };
}

import type { VoiceThemeColors, VoiceBeamColorVariant } from './types';
import { toRgb } from './color';

/**
 * Per-theme presets. Tuned against border-beam's `line` type on the same
 * dark/light stages, so the two read as one family when used side by side.
 */
export const themePresets: Record<'dark' | 'light', VoiceThemeColors> = {
  dark: {
    strokeOpacity: 1.16,
    innerOpacity: 0.47,
    bloomOpacity: 0.89,
    innerShadow: 'rgba(255, 255, 255, 0.1)',
    saturation: 1.2,
    brightness: 1.1,
  },
  // Light sits on a white surface: the deep light palettes at far higher
  // opacity than the dark preset's pastels need, a touch less saturation
  // and no brightness lift (which would wash them toward white).
  light: {
    strokeOpacity: 1.2,
    innerOpacity: 0.85,
    bloomOpacity: 0.5,
    innerShadow: 'rgba(0, 0, 0, 0.08)',
    saturation: 1.6,
    brightness: 0.95,
    // A wider, quicker hue drift on white, nudged 5° warmer.
    hueRange: 40,
    hueDuration: 8.5,
    hueBase: 5,
    // Tuned in the Studio on the chat input.
    strength: 0.8,
    bandStrength: 1.7,
  },
};

/**
 * Lobe geometry, in px for a ~350px-wide reference element. Seven soft
 * ellipses fan out from the bottom center: the centre lobe follows the low
 * band, its neighbours the mids, the outer pair the highs and the far pair
 * the mids again, so a voice makes the colours ripple outward instead of
 * one blob pumping. `x` is the resting offset from centre; the driver
 * slides every lobe along by the flow phase (wrapping at ±LOBE_SPAN/2 so
 * the colours cycle through the centre) and it scales with the spread so
 * a loud sound pushes the side lobes apart.
 */
export interface VoiceLobe {
  x: number;
  w: number;
  h: number;
  band: 0 | 1 | 2;
}

export const voiceLobes: readonly VoiceLobe[] = [
  { x: 0, w: 74, h: 46, band: 0 },
  { x: -36, w: 54, h: 40, band: 1 },
  { x: 36, w: 54, h: 40, band: 1 },
  { x: -72, w: 48, h: 32, band: 2 },
  { x: 72, w: 48, h: 32, band: 2 },
  { x: -108, w: 42, h: 26, band: 1 },
  { x: 108, w: 42, h: 26, band: 1 },
];

/** Resting distance between neighbouring lobes, px. */
export const LOBE_SPACING = 36;
/** Width of the ring the lobes travel around, px — one full turn of the flow. */
export const LOBE_SPAN = LOBE_SPACING * voiceLobes.length;

/**
 * Seven colours per palette, one per lobe (centre first, then pairs). Light
 * palettes use deeper values because they sit on a white surface at far
 * lower opacity.
 */
export const voicePalettes: Record<VoiceBeamColorVariant, { dark: string[]; light: string[] }> = {
  colorful: {
    dark: [
      'rgb(255, 70, 120)',
      'rgb(60, 190, 255)',
      'rgb(175, 70, 255)',
      'rgb(60, 220, 130)',
      'rgb(255, 150, 40)',
      'rgb(90, 100, 255)',
      'rgb(40, 200, 190)',
    ],
    // Candy on white: pinks, sky, lavender, mint, peach, periwinkle,
    // aqua — pastel bodies that the light preset's saturation lifts.
    // Candy on white: gold, sky, violet, rose, peach, periwinkle, aqua —
    // tuned in the Studio; the light preset's saturation lifts them.
    light: [
      'rgb(255, 201, 21)',
      'rgb(126, 196, 255)',
      'rgb(180, 40, 230)',
      'rgb(235, 100, 160)',
      'rgb(255, 176, 122)',
