      'rgb(175, 115, 5)',
      'rgb(195, 150, 20)',
    ],
  },
};

/** rgb(...) -> rgba(..., alpha); anything else passes through. */
function withAlpha(color: string, alpha: number): string {
  const m = color.match(/^rgb\(\s*([\d.]+)\s*,\s*([\d.]+)\s*,\s*([\d.]+)\s*\)$/);
  if (!m) return color;
  return `rgba(${m[1]}, ${m[2]}, ${m[3]}, ${alpha.toFixed(2)})`;
}

/** Scales a tuned blur radius by `glowSize`, kept above 0 so a layer never collapses to a hard edge. */
function scaleBlur(px: number, glowSize = 1): number {
  return Math.max(0.5, Math.round(px * glowSize * 100) / 100);
}

/** A lobe centre: the cluster offset (`--vb-cx`, px — 0 unless processing
 *  carries the whole beam sideways) plus its own driven offset (`--vb-xN`),
 *  spread by the level. */
function lobeX(index: number, id: string): string {
  return `calc(50% + (var(--vb-cx-${id}) + var(--vb-x${index}-${id})) * var(--vb-w-${id}) * var(--vb-z-${id}, 1))`;
}

interface LobeLayerOptions {
  id: string;
  colors: string[];
  alpha: number;
  /** Width / height multipliers on the tuned lobe geometry. */
  sw: number;
  sh: number;
  /** Vertical offset of the lobe centre from the bottom edge, px (positive = below). */
  y: number;
  /** Where the gradient fades out, 0–100. */
  fade: number;
  /** Only the first N lobes (bloom uses the inner five). */
  count?: number;
}

function lobeGradients({ id, colors, alpha, sw, sh, y, fade, count }: LobeLayerOptions): string {
  // The bloom paints every lobe too: with the flow on, any of them can be
  // the one passing through the centre.
  const lobes = count ? voiceLobes.slice(0, count) : voiceLobes;
  return lobes
    .map((lobe, i) => {
      const color = alpha >= 1 ? colors[i % colors.length] : withAlpha(colors[i % colors.length], alpha);
      const w = `calc(${Math.round(lobe.w * sw)}px * var(--vb-w-${id}) * var(--vb-z-${id}, 1))`;
      const h = `calc(${Math.round(lobe.h * sh)}px * var(--vb-h-${id}) * var(--vb-l${i}-${id}) * var(--vb-z-${id}, 1))`;
      // `--vb-yN` lifts the lobe along the element's corner arc while the
      // beam travels through it (processing).
      const yStr = `calc(100% + (${y}px + var(--vb-y${i}-${id})) * var(--vb-z-${id}, 1))`;
      return `radial-gradient(ellipse ${w} ${h} at ${lobeX(i, id)} ${yStr}, ${color} 0%, transparent ${fade}%)`;
    })
    .join(',\n    ');
}

export interface GenerateVoiceStylesOptions {
  id: string;
  borderRadius: number;
  borderWidth: number;
  strokeOpacity: number;
  innerOpacity: number;
  bloomOpacity: number;
  innerShadow: string;
  colorVariant: VoiceBeamColorVariant;
  /** Lobe colours overriding the variant palette (any CSS hex / rgb). */
  colors?: string[];
  brightness: number;
  saturation: number;
  theme: 'dark' | 'light';
  /** The theme's resting hue shift in degrees (the `--voice-hue-base` fallback). */
  hueBase?: number;
  glowSize?: number;
  /** Multiplies every lobe's width / height, all layers. */
  glowWidth?: number;
  glowHeight?: number;
  /** Per-layer scale (both axes) and extra vertical scale. */
  strokeScale?: number;
  innerScale?: number;
  innerHeight?: number;
  bloomScale?: number;
  bloomHeight?: number;
  /** The white hot spot at the centre of the edge. */
  coreSize?: number;
  /** The epicentre wash under the band line: its opacity (0 = no layer) and size. */
  coreLight?: number;
  coreLightWidth?: number;
  coreLightHeight?: number;
  /** The visible ellipse every layer is masked to. */
  rangeWidth?: number;
  rangeHeight?: number;
  /** Where each lobe's gradient fades out; 1 is the tuned edge. */
  softness?: number;
  /** Reference the instance's distortion filter on the inner and bloom layers. */
  distortion?: boolean;
  /** The effect's overall scale, for the px values not carried by a multiplier. */
  scale?: number;
  /** 'dots' and 'lines' drop the glow's layers for the surface's one canvas. */
  look?: 'glow' | 'dots' | 'lines';
}

/**
 * The stylesheet for the surface looks (`dots`, `lines`): the root, the fade
 * in and out, and the one canvas the driver paints the surface on. None of
 * the glow's layers exist, so nothing here reads the per-frame custom
 * properties but the fade.
 */
function generateSurfaceCSS(id: string, borderRadius: number): string {
  return `
@property --vb-opacity-${id} {
  syntax: "<number>";
  initial-value: 0;
  inherits: true;
}

[data-voice-beam="${id}"] {
  position: relative;
  border-radius: ${borderRadius}px;
  overflow: hidden;
  --vb-level-${id}: 0;
  --vb-glow-${id}: 0.4;
}

[data-voice-beam="${id}"][data-active] {
  animation: vb-fade-in-${id} 0.6s ease forwards;
}

[data-voice-beam="${id}"][data-fading] {
  animation: vb-fade-out-${id} 0.5s ease forwards;
}

/* The surface — under the host's content (z 5), above its background. */
[data-voice-beam="${id}"] [data-voice-beam-surface] {
  display: none;
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  border-radius: inherit;
  pointer-events: none;
  z-index: 4;
}

[data-voice-beam="${id}"][data-active] [data-voice-beam-surface],
[data-voice-beam="${id}"][data-fading] [data-voice-beam-surface] {
  display: block;
  opacity: calc(var(--vb-opacity-${id}, 1) * var(--voice-strength, 1));
}

@keyframes vb-fade-in-${id} {
  to { --vb-opacity-${id}: 1; }
}

@keyframes vb-fade-out-${id} {
  from { --vb-opacity-${id}: 1; }
  to { --vb-opacity-${id}: 0; }
}

[data-voice-beam="${id}"][data-paused] {
  animation-play-state: paused !important;
}
`;
}

/**
 * Generate the complete stylesheet for one VoiceBeam instance.
 *
 * Three layers, bottom-centred and clipped to the element, mirror
 * border-beam's `line` type: `::after` paints the colours into the 1px edge
 * ring (the crisp stroke), `::before` the soft light inside the element, and
 * `[data-voice-beam-bloom]` a blurred halo above both. Every size and
 * position multiplies a per-instance custom property the JS driver writes
 * each frame: `--vb-h` (height), `--vb-w` (spread), `--vb-xN` / `--vb-lN`
 * (each lobe's offset along the flow and its amplitude from the band it
 * follows and its distance from centre), `--vb-bh` / `--vb-bendA` (the
 * bend's extra height at the centre and its strength), `--vb-glow`
 * (presence),
 * `--vb-cx` / `--vb-mw` (where the whole beam sits and how narrow its
 * range is — the processing travel) and `--vb-hue` (drift).
 */
export function generateVoiceBeamCSS(options: GenerateVoiceStylesOptions): string {
  if (false && (options.look === 'dots' || options.look === 'lines')) return generateSurfaceCSS(options.id, options.borderRadius);
  const {
    id,
    borderRadius,
    borderWidth,
    strokeOpacity,
    innerOpacity,
    bloomOpacity,
    innerShadow,
    colorVariant,
    colors: customColors,
    brightness,
    saturation,
    theme,
    hueBase = 0,
    glowSize = 1,
    glowWidth = 1,
    glowHeight = 1,
    strokeScale = 1,
    innerScale = 1,
    innerHeight = 1,
    bloomScale = 1,
    bloomHeight = 1,
    coreSize = 1,
    coreLight = 0,
    coreLightWidth = 1,
    coreLightHeight = 1,
    rangeWidth = 1,
    rangeHeight = 1,
    softness = 1,
    distortion = false,
    scale = 1,
  } = options;
  // Corner fades and the inner inset shadow are fixed px otherwise.
  const cornerFade = Math.round(28 * scale * 10) / 10;
  const insetBlur = Math.round(9 * scale * 10) / 10;

  const innerRadius = Math.max(0, borderRadius - borderWidth);
  const fade = Math.round(Math.max(40, Math.min(95, 70 * softness)));
  const gw = (m: number) => glowWidth * m;
  const gh = (m: number) => glowHeight * m;
  const px = (v: number) => Math.round(v * 10) / 10;
  // The layer's raster factor: 1 on the root, 0.5 on a layer rastered at
  // half size and scaled back (see the resolution block). Every length
  // rides it, so the halved layer is the same picture at a quarter of the
  // pixels — done explicitly rather than with `zoom`, which Safari 18
  // applies to the box but not to the px inside it.
  const Z = `var(--vb-z-${id}, 1)`;
  const zpx = (v: number) => `calc(${px(v)}px * ${Z})`;
  const isDark = theme === 'dark';
  const paletteColors = voicePalettes[colorVariant][isDark ? 'dark' : 'light'];
  // A custom palette fills the slots it names; the variant's own colour
  // stays wherever an entry is missing or unparseable.
  const colors = paletteColors.map((c, i) => {
    const custom = customColors?.[i];
    return (custom && toRgb(custom)) || c;
  });
  const isMono = colorVariant === 'mono';

  // Uniform gray at full opacity reads as a harsh bar; soften it.
  const monoMul = isMono ? 0.6 : 1;
  const sStroke = (strokeOpacity * monoMul).toFixed(2);
  const sInner = (innerOpacity * monoMul).toFixed(2);
  const sBloom = (bloomOpacity * monoMul).toFixed(2);

  const b = brightness.toFixed(2);
  const s = saturation.toFixed(2);
  const hue = `hue-rotate(calc(var(--voice-hue-base, ${hueBase}deg) + var(--vb-hue-${id})))`;
  // The distortion filter (an SVG feDisplacementMap the component renders
  // inline) goes on the two soft layers only; the edge stroke stays crisp.
  const warp = distortion ? ` url(#vb-distort-${id})` : '';
  const layerFilter = `filter: ${hue} brightness(${b}) saturate(${s});`;
  const innerFilter = `filter: ${hue} brightness(${b}) saturate(${s})${warp};`;
  const bloomFilter = `filter: blur(${zpx(scaleBlur(10, glowSize))}) ${hue} brightness(${b}) saturate(${s});`;
  const bloomWarpFilter = `filter: blur(${zpx(scaleBlur(10, glowSize))}) ${hue} brightness(${b}) saturate(${s})${warp};`;

  // Where the beam sits: centre at rest, carried sideways by `--vb-cx`
  // while processing travels the whole cluster like border-beam's line.
  const beamX = `calc(50% + var(--vb-cx-${id}) * var(--vb-w-${id}) * ${Z})`;

  // A hot white core at the very centre of the edge — the "light source"
  // the colours fan out from. Black on light so the edge still reads.
  const coreY = `calc(100% + (2px + var(--vb-cy-${id})) * ${Z})`;

  // The bend: the glow's ceiling. The ellipse the stroke and inner light are
  // masked to gets `--vb-bh` extra height at the centre as the voice rises,
  // so its top contour humps upward. The band that traces it is drawn on
  // the canvas layer by the driver (an organic bell, not an ellipse), so
  // nothing about it lives here except the layer's own rule below.
  const highlight = isDark
    ? `radial-gradient(ellipse calc(${px(30 * coreSize)}px * var(--vb-w-${id}) * ${Z}) calc(${px(30 * coreSize)}px * var(--vb-h-${id}) * ${Z}) at ${beamX} ${coreY}, rgba(255, 255, 255, 0.45) 0%, rgba(255, 255, 255, 0.14) 30%, transparent 65%)`
    : `radial-gradient(ellipse calc(${px(40 * coreSize)}px * var(--vb-w-${id}) * ${Z}) calc(${px(30 * coreSize)}px * var(--vb-h-${id}) * ${Z}) at ${beamX} ${coreY}, rgba(0, 0, 0, 0.55) 0%, rgba(0, 0, 0, 0.22) 35%, transparent 70%)`;

  const strokeGradients = lobeGradients({ id, colors, alpha: 1, sw: gw(strokeScale), sh: gh(strokeScale), y: 2, fade });
  const innerGradients = lobeGradients({ id, colors, alpha: 0.46, sw: gw(0.9 * innerScale), sh: gh(0.9 * innerScale * innerHeight), y: 0, fade });
  const bloomGradients = lobeGradients({ id, colors, alpha: isDark ? 0.9 : 0.7, sw: gw(1.15 * bloomScale), sh: gh(1.5 * bloomScale * bloomHeight), y: 0, fade: Math.min(95, fade + 2) });

  // The ellipse every layer is masked to — on the beam, growing with the
  // level; `--vb-mw` narrows it into a beam while processing.
  const edgeMask = (w: number, h: number, mid: number, tail = 0) =>
    `radial-gradient(ellipse calc(${px(w * rangeWidth)}px * var(--vb-w-${id}) * var(--vb-mw-${id}) * ${Z}) calc((${px(h * rangeHeight)}px * var(--vb-h-${id}) + var(--vb-bh-${id})) * ${Z}) at ${beamX} calc(100% + var(--vb-cy-${id}) * ${Z}), white 0%, rgba(255, 255, 255, 0.5) ${mid}%${tail > 0 ? `, rgba(255, 255, 255, ${tail}) 85%` : ''}, transparent 100%)`;

  const opacity = (layer: string, preset: string) =>
    `opacity: calc(var(--vb-opacity-${id}, 1) * var(--vb-glow-${id}) * ${preset} * var(--voice-${layer}-opacity, 1) * var(--voice-strength, 1));`;

  // The inner light's rule body, emitted for the ::before and — with
  // distortion on — for its warped mirror below the band line.
  const innerRule = (selector: string, head: string, clip: string, filter: string) => `${selector} {
  ${head}
  position: absolute;
  inset: 0;
  border-radius: ${zpx(borderRadius)};
  background: ${innerGradients};
  box-shadow: inset 0 0 ${zpx(insetBlur)} 1px ${innerShadow};
  -webkit-mask-image:
    ${edgeMask(170, 64, 45, 0.3)},
    linear-gradient(white, transparent ${zpx(cornerFade)}, transparent calc(100% - ${cornerFade}px * ${Z}), white),
    linear-gradient(to right, white, transparent ${zpx(cornerFade)}, transparent calc(100% - ${cornerFade}px * ${Z}), white);
  -webkit-mask-composite: source-in, source-over;
  mask-image:
    ${edgeMask(170, 64, 45, 0.3)},
    linear-gradient(white, transparent ${zpx(cornerFade)}, transparent calc(100% - ${cornerFade}px * ${Z}), white),
    linear-gradient(to right, white, transparent ${zpx(cornerFade)}, transparent calc(100% - ${cornerFade}px * ${Z}), white);
  mask-composite: intersect, add;
  pointer-events: none;
  /* Its own compositing layer: WebKit otherwise re-rasterizes the
     filtered layer into the parent every frame on the CPU (a phone-sized
     host runs at a sixth of the frame rate without this). */
  will-change: transform;
  z-index: 1;
  ${clip}
  ${opacity('inner', sInner)}
  ${filter}
}`;


  return `
@property --vb-opacity-${id} {
  syntax: "<number>";
  initial-value: 0;
  inherits: true;
}

[data-voice-beam="${id}"] {
  position: relative;
  border-radius: ${borderRadius}px;
  overflow: hidden;
  --vb-h-${id}: 0.8;
  --vb-w-${id}: 1;
${voiceLobes.map((lobe, i) => `  --vb-x${i}-${id}: ${lobe.x}px;
  --vb-l${i}-${id}: 1;
  --vb-y${i}-${id}: 0px;`).join('\n')}
  --vb-glow-${id}: 0.4;
  --vb-z-${id}: 1;
  --vb-cx-${id}: 0px;
  --vb-cy-${id}: 0px;
  --vb-bh-${id}: 0px;
  --vb-bendA-${id}: 0;
  --vb-mw-${id}: 1;
  --vb-hue-${id}: 0deg;
  --vb-level-${id}: 0;
}

[data-voice-beam="${id}"][data-active] {
  animation: vb-fade-in-${id} 0.6s ease forwards;
}

[data-voice-beam="${id}"][data-fading] {
  animation: vb-fade-out-${id} 0.5s ease forwards;
}

/* Stroke — the colours painted into the 1px edge ring, masked to the centred ellipse. */
[data-voice-beam="${id}"][data-active]::after,
[data-voice-beam="${id}"][data-fading]::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: ${zpx(innerRadius)};
  padding: ${zpx(borderWidth)};
  clip-path: inset(0 round ${zpx(borderRadius)});
  background:
    ${highlight},
    ${strokeGradients};
  -webkit-mask:
    ${edgeMask(170, 64, 45)},
    linear-gradient(#fff 0 0) content-box,
    linear-gradient(#fff 0 0);
  -webkit-mask-composite: source-in, xor;
  mask:
    ${edgeMask(170, 64, 45)},
    linear-gradient(#fff 0 0) content-box,
    linear-gradient(#fff 0 0);
  mask-composite: intersect, exclude;
  pointer-events: none;
  /* Its own compositing layer: WebKit otherwise re-rasterizes the
     filtered layer into the parent every frame on the CPU (a phone-sized
     host runs at a sixth of the frame rate without this). */
  will-change: transform;
  z-index: 2;
  ${opacity('stroke', sStroke)}
  ${layerFilter}
}

/* Inner glow — soft light inside the element, faded off at the corners.
   With distortion on, this copy is clipped to ABOVE the band line (the
   polygon the driver writes each frame) and a mirror layer below carries
   the displacement filter, so only the glow under the line warps. */
${innerRule(`[data-voice-beam="${id}"][data-active]::before,\n[data-voice-beam="${id}"][data-fading]::before`, `content: "";`, distortion ? `clip-path: var(--vb-clip-above-${id}, inset(0 round ${borderRadius}px));` : `clip-path: inset(0 round ${borderRadius}px);`, layerFilter)}
${distortion ? innerRule(`[data-voice-beam="${id}"][data-active] [data-voice-beam-warp="inner"],\n[data-voice-beam="${id}"][data-fading] [data-voice-beam-warp="inner"]`, 'display: block;', `clip-path: var(--vb-clip-below-${id}, inset(0 round ${borderRadius}px));`, innerFilter) : ''}

/* Bloom — the blurred halo, tallest of the three, above the content. */
[data-voice-beam="${id}"] [data-voice-beam-bloom],
[data-voice-beam="${id}"] [data-voice-beam-warp] {
  display: none;
  position: absolute;
  inset: 0;
  border-radius: ${zpx(innerRadius)};
  pointer-events: none;
  /* Its own compositing layer: WebKit otherwise re-rasterizes the
     filtered layer into the parent every frame on the CPU (a phone-sized
     host runs at a sixth of the frame rate without this). */
  will-change: transform;
  opacity: 0;
}

[data-voice-beam="${id}"] [data-voice-beam-bloom],
[data-voice-beam="${id}"] [data-voice-beam-warp="bloom"] {
  -webkit-mask: ${edgeMask(200, 130, 35)};
  mask: ${edgeMask(200, 130, 35)};
  background: ${bloomGradients};
  z-index: 3;
}

[data-voice-beam="${id}"][data-active] [data-voice-beam-bloom],
[data-voice-beam="${id}"][data-fading] [data-voice-beam-bloom] {
  display: block;
  clip-path: ${distortion ? `var(--vb-clip-above-${id}, inset(0 round ${borderRadius}px))` : `inset(0 round ${borderRadius}px)`};
  ${opacity('bloom', sBloom)}
  ${bloomFilter}
}
${distortion ? `
[data-voice-beam="${id}"][data-active] [data-voice-beam-warp="bloom"],
[data-voice-beam="${id}"][data-fading] [data-voice-beam-warp="bloom"] {
  display: block;
  clip-path: var(--vb-clip-below-${id}, inset(0 round ${borderRadius}px));
  ${opacity('bloom', sBloom)}
  ${bloomWarpFilter}
}

/* Processing drops the distortion: the driver marks the wrapper once the
   warp has faded out, the warp layers leave the paint and the base layers
   give up their split at the band line. */
[data-voice-beam="${id}"][data-voice-warp="off"]::before,
[data-voice-beam="${id}"][data-voice-warp="off"] [data-voice-beam-bloom] {
  clip-path: inset(0 round ${borderRadius}px);
}

[data-voice-beam="${id}"][data-voice-warp="off"] [data-voice-beam-warp] {
  display: none;
}` : ''}

/* Epicentre — a soft white wash at the source, under the band line (the
   driver's clip; unclipped when no line is drawn), sitting above every
   glow layer and the band's halo so the centre reads lighter than the
   band (same z as the band canvases, painted after them). Sized by the voice like the
   other layers; off unless \`coreLight\` is set (the light theme sets it).
   Up to 1 it is the wash's opacity; past 1 the solid white core widens
   too, for a centre that stays lighter than a strong band. It follows the
   glow's presence but not \`strength\`, which would only dim it. */
${coreLight > 0 ? (() => {
  // Past 1 the wash keeps growing: white is already white, so "brighter"
  // means a wider solid core, a later fade and a larger ellipse — more of
  // the colour beneath washed out. Two stops of boost, to 3.
  const boost = Math.max(0, Math.min(2, coreLight - 1));
  const b1 = Math.min(1, boost);
  const b2 = Math.max(0, boost - 1);
  const grow = 1 + 0.3 * boost;
  const solid = px(45 * b1 + 27 * b2);
  const midStop = px(40 + 25 * b1 + 15 * b2);
  const midAlpha = Math.min(1, 0.55 + 0.35 * b1 + 0.1 * b2).toFixed(2);
  const endStop = px(72 + 14 * b1 + 8 * b2);
  return `[data-voice-beam="${id}"] [data-voice-beam-core] {
  display: none;
  position: absolute;
  inset: 0;
  border-radius: ${zpx(innerRadius)};
  overflow: hidden;
  pointer-events: none;
  /* Its own compositing layer: WebKit otherwise re-rasterizes the
     filtered layer into the parent every frame on the CPU (a phone-sized
     host runs at a sixth of the frame rate without this). */
  will-change: transform;
  /* The blur sits on this wrapper and the band-line clip on the child,
     so the cut edge is blurred too rather than left hard. */
  filter: blur(${zpx(scaleBlur(8, glowSize))});
  z-index: 4;
}

[data-voice-beam="${id}"] [data-voice-beam-core] > div {
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse calc(${px(120 * coreLightWidth * grow * scale)}px * var(--vb-w-${id}) * ${Z}) calc((${px(70 * coreLightHeight * grow * scale)}px * var(--vb-h-${id}) + var(--vb-bh-${id})) * ${Z}) at ${beamX} calc(100% + var(--vb-cy-${id}) * ${Z}), white 0%, white ${solid}%, rgba(255, 255, 255, ${midAlpha}) ${midStop}%, transparent ${endStop}%);
  clip-path: var(--vb-clip-below-${id}, none);
}

[data-voice-beam="${id}"][data-active] [data-voice-beam-core],
[data-voice-beam="${id}"][data-fading] [data-voice-beam-core] {
  display: block;
  opacity: calc(var(--vb-opacity-${id}, 1) * min(1, var(--vb-glow-${id}) * ${Math.min(1, coreLight).toFixed(2)} * ${(1.6 + 1.4 * boost).toFixed(2)}) * var(--voice-core-light-opacity, 1));
}
`; })() : ''}
/* Band — the canvas the driver draws the bend's contour on: an organic
   bell with chromatic fringes. Fades with the root, follows the strength
   and turns with the hue drift like the other layers. */
[data-voice-beam="${id}"] [data-voice-beam-band],
[data-voice-beam="${id}"] [data-voice-beam-band-halo] {
  display: none;
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
  /* Its own compositing layer: WebKit otherwise re-rasterizes the
     filtered layer into the parent every frame on the CPU (a phone-sized
     host runs at a sixth of the frame rate without this). */
  will-change: transform;
  z-index: 4;
}

[data-voice-beam="${id}"][data-active] [data-voice-beam-band],
[data-voice-beam="${id}"][data-fading] [data-voice-beam-band],
[data-voice-beam="${id}"][data-active] [data-voice-beam-band-halo],
[data-voice-beam="${id}"][data-fading] [data-voice-beam-band-halo] {
  display: block;
  opacity: calc(var(--vb-opacity-${id}, 1) * var(--voice-band-opacity, 1) * var(--voice-strength, 1));
  /* The blur vars are 0 where the canvas blurs its own strokes; where the
     2D context has no filter (WebKit) the driver sets them and the layers
     are blurred here instead — the ridge on the band canvas, its wider
     halo on the canvas beneath. */
  filter: blur(var(--vb-band-blur-${id}, 0px)) ${hue} brightness(${b}) saturate(${s});
}

[data-voice-beam="${id}"][data-active] [data-voice-beam-band-halo],
[data-voice-beam="${id}"][data-fading] [data-voice-beam-band-halo] {
  filter: blur(var(--vb-band-halo-blur-${id}, 0px)) ${hue} brightness(${b}) saturate(${s});
}

/* Resolution. The soft layers — inner light and its warp mirror, bloom and
   its mirror, the epicentre — are rastered at half size and scaled back
   up by the compositor: the box is halved, every length inside rides the
   layer's factor \`--vb-z\` at 0.5 (the driver also writes the band-line
   clips at half scale), and the will-change transform is rastered
   pre-scale where the engine does that (Chromium, Safari 18). For blurred
   gradients that is the same picture at a quarter of the raster and
   filter work, which is what a phone at 3x runs out of. The 1px stroke
   stays full-res on every screen: at half size it is half a CSS pixel,
   which a 3x phone rasters into a faint smear instead of the hairline,
   and the layer is cheap (no blur). The component sets
   \`data-voice-halfres\`. */
[data-voice-beam="${id}"][data-voice-halfres]::before,
[data-voice-beam="${id}"][data-voice-halfres] [data-voice-beam-warp],
[data-voice-beam="${id}"][data-voice-halfres] [data-voice-beam-bloom],
[data-voice-beam="${id}"][data-voice-halfres] [data-voice-beam-core] {
  --vb-z-${id}: 0.5;
  inset: auto;
  left: 0;
  top: 0;
  width: 50%;
  height: 50%;
  transform: translateZ(0) scale(2);
  transform-origin: 0 0;
}
${distortion ? `[data-voice-beam="${id}"][data-voice-halfres][data-active]::before,
[data-voice-beam="${id}"][data-voice-halfres][data-fading]::before,
[data-voice-beam="${id}"][data-voice-halfres][data-active] [data-voice-beam-bloom],
[data-voice-beam="${id}"][data-voice-halfres][data-fading] [data-voice-beam-bloom] {
  clip-path: var(--vb-clip-above-z-${id}, inset(0 round ${zpx(borderRadius)}));
}
[data-voice-beam="${id}"][data-voice-halfres][data-active] [data-voice-beam-warp],
[data-voice-beam="${id}"][data-voice-halfres][data-fading] [data-voice-beam-warp] {
  clip-path: var(--vb-clip-below-z-${id}, inset(0 round ${zpx(borderRadius)}));
}
/* Processing (warp off): the mirrors are gone, so the base layers paint
   the whole box again — this must outweigh the split above. */
[data-voice-beam="${id}"][data-voice-halfres][data-voice-warp="off"]::before,
[data-voice-beam="${id}"][data-voice-halfres][data-voice-warp="off"] [data-voice-beam-bloom] {
  clip-path: inset(0 round ${zpx(borderRadius)});
}` : `[data-voice-beam="${id}"][data-voice-halfres][data-active]::before,
[data-voice-beam="${id}"][data-voice-halfres][data-fading]::before,
[data-voice-beam="${id}"][data-voice-halfres][data-active] [data-voice-beam-bloom],
[data-voice-beam="${id}"][data-voice-halfres][data-fading] [data-voice-beam-bloom] {
  clip-path: inset(0 round ${zpx(borderRadius)});
}`}
[data-voice-beam="${id}"][data-voice-halfres] [data-voice-beam-core] > div {
  clip-path: var(--vb-clip-below-z-${id}, none);
}
@keyframes vb-fade-in-${id} {
  to { --vb-opacity-${id}: 1; }
}

@keyframes vb-fade-out-${id} {
  from { --vb-opacity-${id}: 1; }
  to { --vb-opacity-${id}: 0; }
}

[data-voice-beam="${id}"][data-paused],
[data-voice-beam="${id}"][data-paused]::after,
[data-voice-beam="${id}"][data-paused]::before,
[data-voice-beam="${id}"][data-paused] [data-voice-beam-bloom] {
  animation-play-state: paused !important;
}
`;
}

"use client";

import { voiceLobes } from './styles';
import type { VoiceDriverConfig } from './voiceDriver';

/**
 * The surface looks — `look="dots"` and `look="lines"`.
 *
 * A sheet seen in perspective along the bottom of the element, gently
 * domed, drawn as a field of dots (the dotted language of thinking-orbs) or
 * as lines running across it: depth carried by size and ink alone, plain 2D
 * canvas paths, no filters, so every engine draws the same picture.
 *
 * The voice raises hills out of the sheet — one per lobe, so the spectrum
 * reads as a landscape, drifting sideways with the flow and gathering into
 * one travelling mound while processing. Every point of the sheet carries
 * its own height and velocity: it is lifted toward the voice on a fast
 * spring, keeps its momentum when the voice stops, and then falls under
 * gravity, landing on the sheet with a small bounce. Lifted parts catch the
 * light.
 *
 * The sheet's own shape is the surface props': how tall it stands, how far
 * it arcs, and its tails — the ends rising into the corners or dropping
 * away, and dissolving into the sides. Lines are solid unless `seeThrough`:
 * a raised ridge hides the lines behind it, as a sheet would.
 */

/** Dot spacing at scale 1, px, measured on the nearest row. */
const GAP = 4.6;
/** Line spacing at scale 1, px on the nearest row: between the rows, and between the columns. */
const LINE_ROW_GAP = 5.6;
const LINE_COL_GAP = 10;
/** Points along a line, px apart on the nearest row — fine enough that a hill stays round. */
const LINE_STEP = 3;
/** Camera pitch: how steeply the sheet is seen from above. */
const TILT = 0.4;
/** Perspective: the far edge renders at this share of the near edge's size. */
const K_FAR = 0.5;
/** A point whose tone is below this is not drawn. */
const S_MIN = 0.03;
/** Ink buckets: dots are batched into one path per shade, and a line's gradient takes its stops from the same inks. */
const BUCKETS = 20;
/** Above this many points the grid opens up, so a large host stays cheap. */
const MAX_DOTS = 6000;
const MAX_LINE_POINTS = 9000;
const MAX_LINE_ROWS = 120;
/** Most colour stops along one line. */
const LINE_STOPS = 40;
const DPR_MAX = 2;
/** How high a full tail lifts the ends, × the sheet's height. */
const TAIL_LIFT = 0.6;
/** A line's tension, per second: how fast each point is pulled toward its
 *  neighbours along the row, so a falling line stays a curve. */
const LINE_TENSION = 22;
/** A square dot's half-side for the ink of a round one of the same radius (equal area). */
const SQUARE = Math.sqrt(Math.PI) / 2;
const TWO_PI = Math.PI * 2;

// ── Noise ─────────────────────────────────────────────────────────────
// A tileable value-noise table, built once and sampled with a smoothstep
// bilinear — a handful of lookups per sample.

const NOISE_N = 64;
const NOISE_MASK = NOISE_N - 1;
const NOISE = (() => {
  const table = new Float32Array(NOISE_N * NOISE_N);
  let s = 0x2545f491;
  for (let i = 0; i < table.length; i++) {
    s ^= s << 13;
    s ^= s >>> 17;
    s ^= s << 5;
    table[i] = (s >>> 0) / 4294967296;
  }
  return table;
})();

function vnoise(x: number, y: number): number {
  const xf = Math.floor(x);
  const yf = Math.floor(y);
  let fx = x - xf;
  let fy = y - yf;
  fx = fx * fx * (3 - 2 * fx);
  fy = fy * fy * (3 - 2 * fy);
  const x0 = xf & NOISE_MASK;
  const y0 = yf & NOISE_MASK;
  const x1 = (x0 + 1) & NOISE_MASK;
  const y1 = (y0 + 1) & NOISE_MASK;
  const a = NOISE[y0 * NOISE_N + x0];
  const b = NOISE[y0 * NOISE_N + x1];
  const c = NOISE[y1 * NOISE_N + x0];
  const d = NOISE[y1 * NOISE_N + x1];
  return a + (b - a) * fx + (c - a) * fy + (a - b - c + d) * fx * fy;
}

function smoothstep(a: number, b: number, x: number): number {
  const t = Math.max(0, Math.min(1, (x - a) / (b - a)));
  return t * t * (3 - 2 * t);
}

/** Deterministic 0–1 sequence for the per-dot seeds. */
function rng(seed: number): () => number {
  let s = seed >>> 0 || 1;
  return () => {
    s ^= s << 13;
    s ^= s >>> 17;
    s ^= s << 5;
    return (s >>> 0) / 4294967296;
  };
}

// ── State ─────────────────────────────────────────────────────────────

export interface SurfaceState {
  canvas: HTMLCanvasElement;
  ctx: CanvasRenderingContext2D;
  /** What the grid was built for; a change rebuilds it (and resets the physics). */
  key: string;
  /** The sheet's frame: depth, the depth the hills stand at, and the perspective. */
  depth: number;
  hillZ: number;
  persp: number;
  /** Grid points, far rows first: world position, the row, a per-point seed. */
  n: number;
  gx: Float32Array;
  gz: Float32Array;
  row: Uint16Array;
  seed: Float32Array;
  rows: number;
  rowZ: Float32Array;
  /** Where each row's points start, in draw order (far first); for lines also
   *  the lattice index of its first point — the columns run through every
   *  `colEvery`th index, the same in every row. */
  rowStart: Int32Array;
  rowFirst: Int32Array;
  colEvery: number;
  /** Physics: each point's height above the sheet and its vertical velocity. */
  h: Float32Array;
  v: Float32Array;
  /** Per frame: every point's position, its tone (−1 when it is not drawn) and, for dots, its radius. */
  px: Float32Array;
  py: Float32Array;
  ps: Float32Array;
  pr: Float32Array;
  /** Dots: each drawn point's ink bucket, and the drawn points sorted by it. */
  pb: Uint8Array;
  order: Int32Array;
}

export function createSurfaceState(canvas: HTMLCanvasElement): SurfaceState | null {
  const ctx = canvas.getContext('2d');
  if (!ctx) return null;
  const f = new Float32Array(0);
  const i = new Int32Array(0);
  return {
    canvas,
    ctx,
    key: '',
    depth: 1,
    hillZ: 0,
    persp: 0,
    n: 0,
    gx: f,
    gz: f,
    row: new Uint16Array(0),
    seed: f,
    rows: 0,
    rowZ: f,
    rowStart: i,
    rowFirst: i,
    colEvery: 1,
    h: f,
    v: f,
    px: f,
    py: f,
    ps: f,
    pr: f,
    pb: new Uint8Array(0),
    order: i,
  };
}

/** The sheet's frame for a footprint: its depth and perspective. */
function frameFor(footprint: number): { depth: number; persp: number } {
  const depth = footprint / (Math.sin(TILT) * K_FAR);
  return { depth, persp: (1 / K_FAR - 1) / depth };
}

function commit(
  st: SurfaceState,
  pts: { x: number[]; z: number[]; r: number[]; seed: number[] },
  rows: number,
  rowZ: Float32Array,
  rowStart: Int32Array,
  rowFirst: Int32Array,
  colEvery: number,
  depth: number,
  persp: number
): void {
  st.n = pts.x.length;
  st.gx = Float32Array.from(pts.x);
  st.gz = Float32Array.from(pts.z);
  st.row = Uint16Array.from(pts.r);
  st.seed = Float32Array.from(pts.seed);
  st.rows = rows;
  st.rowZ = rowZ;
  st.rowStart = rowStart;
  st.rowFirst = rowFirst;
  st.colEvery = colEvery;
  st.depth = depth;
  st.hillZ = depth * 0.42;
  st.persp = persp;
  st.h = new Float32Array(st.n);
  st.v = new Float32Array(st.n);
  st.px = new Float32Array(st.n);
  st.py = new Float32Array(st.n);
  st.ps = new Float32Array(st.n);
  st.pr = new Float32Array(st.n);
  st.pb = new Uint8Array(st.n);
  st.order = new Int32Array(st.n);
}

/**
 * The dot sheet: rows running into the depth, each row's dots spaced evenly
 * in the world so perspective packs the far rows finer — which is what makes
 * it read as a surface rather than a screen. Each row only spans the width
 * it is seen at, so no dot is simulated off to the side.
 */
function buildDots(st: SurfaceState, cw: number, gap: number, footprint: number): void {
  const { depth, persp } = frameFor(footprint);
  const dz = (gap * 0.82) / Math.sin(TILT);
  const rows = Math.max(2, Math.ceil(depth / dz) + 1);
  const rowZ = new Float32Array(rows);
  const rowStart = new Int32Array(rows + 1);
  const pts = { x: [] as number[], z: [] as number[], r: [] as number[], seed: [] as number[] };
  const rand = rng(0x9e3779b9);
  // Far rows first, so the draw order runs back to front.
  for (let r = rows - 1, d = 0; r >= 0; r--, d++) {
    const z = Math.min(depth, r * dz);
    rowZ[r] = z;
    rowStart[d] = pts.x.length;
    const k = 1 / (1 + persp * z);
    const half = (cw / 2 + gap * 2) / k;
    const cols = Math.ceil((2 * half) / gap);
    // Alternate rows sit half a step over: a hex weave, not a checkerboard.
    const off = r & 1 ? gap / 2 : 0;
    for (let c = 0; c <= cols; c++) {
      pts.x.push(-half + off + c * gap);
      pts.z.push(z);
      pts.r.push(r);
      pts.seed.push(rand());
    }
  }
  rowStart[rows] = pts.x.length;
  commit(st, pts, rows, rowZ, rowStart, new Int32Array(rows), 1, depth, persp);
}

/**
 * The line sheet: the same rows, but every row's points on one lattice
 * across the width, so the columns line up through the depth and converge
 * with the perspective. The points are finer than the lines they draw, and
 * their seeds vary smoothly along a row, so a falling line stays a curve.
 */
function buildLines(st: SurfaceState, cw: number, rowGap: number, step: number, colEvery: number, footprint: number): void {
  const { depth, persp } = frameFor(footprint);
  const dz = rowGap / Math.sin(TILT);
  const rows = Math.max(2, Math.floor(depth / dz) + 1);
  const rowZ = new Float32Array(rows);
  const rowStart = new Int32Array(rows + 1);
  const rowFirst = new Int32Array(rows);
  const pts = { x: [] as number[], z: [] as number[], r: [] as number[], seed: [] as number[] };
  for (let r = rows - 1, d = 0; r >= 0; r--, d++) {
    const z = r * dz;
    rowZ[r] = z;
    rowStart[d] = pts.x.length;
    const k = 1 / (1 + persp * z);
    const reach = Math.ceil((cw / 2 + step * 2) / k / step);
    rowFirst[d] = -reach;
    for (let i = -reach; i <= reach; i++) {
      const x = i * step;
      pts.x.push(x);
      pts.z.push(z);
      pts.r.push(r);
      pts.seed.push(vnoise(x * 0.045 + 7.3, r * 0.61 + 1.7));
    }
  }
  rowStart[rows] = pts.x.length;
  commit(st, pts, rows, rowZ, rowStart, rowFirst, colEvery, depth, persp);
}

/** One frame of the voice, as the driver has it. */
export interface SurfaceFrame {
  cw: number;
  ch: number;
  /** Each lobe's centre along the edge (element px), and its amplitude from the band it follows. */
  lobeX: Float32Array;
  lobeL: Float32Array;
  /** The spread multiplier (0.85 at rest, wider with the voice). */
  w: number;
  /** How high the hills stand, 0–1: the voice on a fast envelope, or the held level while processing. */
  lift: number;
  /** Overall presence, 0.15–1. */
  glow: number;
  t: number;
  dt: number;
  /** Unwrapped flow travel, px — the ripple rides it. */
  drift: number;
}

// Per-frame scratch, shared: frames are painted one at a time.
const LOBES = voiceLobes.length;
const hillX = new Float32Array(LOBES);
const hillA = new Float32Array(LOBES);
const hillIw = new Float32Array(LOBES);
let rowDepth = new Float32Array(0);
const bucketCount = new Int32Array(BUCKETS);
const bucketAt = new Int32Array(BUCKETS);
const bucketStyle: string[] = new Array(BUCKETS);
let clearStyle = '';
let bucketStyleKey = '';
const bucketScale = BUCKETS / (1 - S_MIN);

/** Grey and alpha for a tone: faint a translucent grey, lit solid white — near-black ink on the light theme. */
function ink(s: number, alpha: number, dark: boolean): string {
  const g = dark ? Math.round(185 + 70 * s) : Math.round(120 - 105 * s);
  return `rgba(${g},${g},${g},${alpha.toFixed(3)})`;
}

function inkStyles(dark: boolean): void {
  const key = dark ? 'd' : 'l';
  if (bucketStyleKey === key) return;
  for (let b = 0; b < BUCKETS; b++) {
    const s = S_MIN + ((b + 0.5) / BUCKETS) * (1 - S_MIN);
    bucketStyle[b] = ink(s, 0.08 + 0.92 * Math.pow(s, 1.05), dark);
  }
  // A line fades out through its own grey, not through black.
  clearStyle = ink(S_MIN, 0, dark);
  bucketStyleKey = key;
}

function bucketOf(s: number): number {
  const b = Math.floor((Math.min(s, 0.99999) - S_MIN) * bucketScale);
  return b < 0 ? 0 : b;
}

export function drawSurface(st: SurfaceState, config: VoiceDriverConfig, f: SurfaceFrame): void {
  const { cw, ch } = f;
  const lines = config.look === 'lines';
  const dark = config.theme === 'dark';
  const scale = Math.max(0.05, config.scale);
  const sc = Math.sqrt(scale);
  const texture = Math.max(0, Math.min(1, config.texture));
  const motion = config.reducedMotion ? 0 : 1;
  const t = f.t * motion;
  const dt = f.dt;

  // ── Canvas ───────────────────────────────────────────────────────────
  const dpr = Math.min(DPR_MAX, (typeof window !== 'undefined' && window.devicePixelRatio) || 1);
  const pw = Math.round(cw * dpr);
  const ph = Math.round(ch * dpr);
  const canvas = st.canvas;
  if (canvas.width !== pw || canvas.height !== ph) {
    canvas.width = pw;
    canvas.height = ph;
  }
  const ctx = st.ctx;
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  ctx.clearRect(0, 0, cw, ch);

  // ── The sheet ────────────────────────────────────────────────────────
  // It lies along the bottom: about half a short host's height, capped for
  // a tall one, where the hills get the room above it instead — times the
  // host's own `surfaceHeight`.
  const footprint = Math.max(
    10,
    Math.min(ch * 0.95, Math.min(ch * 0.5, 64 * Math.pow(scale, 0.9)) * Math.max(0.1, config.surfaceHeight))
  );
  const sinT = Math.sin(TILT);
  const cosT = Math.cos(TILT);
  if (lines) {
    const lineGap = Math.max(0.3, config.lineGap);
    const rowGap = Math.max(LINE_ROW_GAP * sc * lineGap, footprint / (K_FAR * MAX_LINE_ROWS));
    const colGap = LINE_COL_GAP * sc * lineGap;
    let step = LINE_STEP * sc;
    // A rough count: the rows times the points of an average row.
    const estimate = (footprint / (K_FAR * rowGap) + 1) * 1.5 * (cw / step + 4);
    if (estimate > MAX_LINE_POINTS) step *= estimate / MAX_LINE_POINTS;
    let colEvery = Math.round(colGap / step);
    if (colEvery >= 1) step = colGap / colEvery;
    else colEvery = 1;
    const key = `l|${cw}|${ch}|${rowGap.toFixed(3)}|${step.toFixed(3)}|${colEvery}|${footprint.toFixed(2)}`;
    if (st.key !== key) {
      buildLines(st, cw, rowGap, step, colEvery, footprint);
      st.key = key;
    }
  } else {
    let gap = GAP * sc * Math.max(0.3, config.dotGap);
    // A rough count: the sheet's rows times the columns of an average row.
    const estimate = (footprint / (sinT * K_FAR) / ((gap * 0.82) / sinT)) * (cw / (gap * 0.7));
    if (estimate > MAX_DOTS) gap *= Math.sqrt(estimate / MAX_DOTS);
    const key = `d|${cw}|${ch}|${gap.toFixed(3)}|${footprint.toFixed(2)}`;
    if (st.key !== key) {
      buildDots(st, cw, gap, footprint);
      st.key = key;
    }
  }
  const { depth, hillZ, persp, rows, rowZ } = st;
  const y0 = ch - 1.5 * sc;

  // The arc: the sheet falls away toward the sides and the far edge, so its
  // rows bow like a horizon — `surfaceCurve` times; below 0 it cups instead.
  const curve = config.surfaceCurve;
  const kHill = 1 / (1 + persp * hillZ);
  const edgeX = cw / 2 / kHill;
  const domeX = (curve * 0.32 * footprint) / (edgeX * edgeX);
  const domeZ = (curve * 0.3 * footprint) / Math.max(1, (depth - hillZ) * (depth - hillZ));
  // The tails: from `surfaceTailPosition` of the way out to either side,
  // each row's ends rise (or, below 0, drop) by up to `surfaceTail` of the
  // sheet's height at the edge, on a `surfaceTailCurve` exponent.
  const tailA = config.surfaceTail * TAIL_LIFT * footprint;
  const tailStart = Math.max(0, Math.min(0.98, config.surfaceTailPosition));
  const tailSpan = 1 / (1 - tailStart);
  const tailCurve = Math.max(0.5, config.surfaceTailCurve);
  // How far in from the sides the sheet dissolves, as a share of its half-width.
  const sideFade = Math.max(0, Math.min(1, config.surfaceFade));

  // ── The hills ────────────────────────────────────────────────────────
  // One per lobe, narrow enough that the spectrum reads as separate peaks,
  // standing a little behind the middle of the sheet so the near rows stay
  // low and the landscape rises out of it.
  const L = config.layers;
  const hMax = 64 * config.rangeHeight * config.reach * 0.62;
  for (let i = 0; i < LOBES; i++) {
    const lobe = voiceLobes[i];
    hillX[i] = (f.lobeX[i] - cw / 2) / kHill;
    hillA[i] = hMax * f.lift * f.lobeL[i];
    hillIw[i] = kHill / Math.max(1, lobe.w * L.glowWidth * f.w * 0.42);
  }
  if (rowDepth.length < rows) rowDepth = new Float32Array(rows);
  const zSpread = depth * 0.24;
  for (let r = 0; r < rows; r++) {
    const dzr = (rowZ[r] - hillZ) / zSpread;
    rowDepth[r] = Math.exp(-dzr * dzr);
  }

  // ── Physics ──────────────────────────────────────────────────────────
  // Up: a fast spring toward the voice. Down: momentum, then gravity, then
  // a small bounce on the sheet. Each point's gravity and bounce vary a
  // hair, so a falling hill comes down as a shower rather than a slab.
  const gravity = 1250 * sc * Math.max(0.05, config.gravity);
  const riseK = dt > 0 ? 1 - Math.exp(-dt * 16) : 0;
  const vMax = 900 * sc;
  const bounceMin = 55 * sc;

  // The ripple: a slow undulation the flow carries across the sheet.
  const rippleAmp = texture * 2.8 * sc * (0.5 + 0.5 * f.glow);
  const iRx = 1 / (46 * sc);
  const iRz = 1 / (30 * sc);
  const drift = f.drift * motion;

  const H = st.h;
  const V = st.v;
  const GX = st.gx;
  const GZ = st.gz;
  const ROW = st.row;
  const SEED = st.seed;
  const PX = st.px;
  const PY = st.py;
  const PS = st.ps;
  const PR = st.pr;
  const n = st.n;
  const rBase = 1.02 * sc * Math.max(0.1, config.dotSize);
  const liftRef = 1 / Math.max(1, 0.45 * hMax);
  const presence = 0.55 + 0.45 * f.glow;
  const halfW = cw / 2 + 4;
  const iHalf = 2 / cw;

  if (dt > 0) {
    for (let i = 0; i < n; i++) {
      const X = GX[i];
      const depthW = rowDepth[ROW[i]];

      // Where the voice wants this point.
      let target = 0;
      if (depthW > 0.004) {
        for (let k = 0; k < LOBES; k++) {
          const d = (X - hillX[k]) * hillIw[k];
          const d2 = d * d;
          if (d2 < 9) target += hillA[k] * Math.exp(-d2);
        }
        target *= depthW;
      }

      // Get it there.
      let hh = H[i];
      let vv = V[i];
      if (target >= hh) {
        const next = hh + (target - hh) * riseK;
        vv = Math.min(vMax, (next - hh) / dt);
        hh = next;
      } else {
        const sd = SEED[i];
        vv -= gravity * (0.88 + 0.24 * sd) * dt;
        hh += vv * dt;
        if (hh < target) {
          hh = target;
          vv = vv < -bounceMin && motion ? -vv * (0.16 + 0.18 * sd) : 0;
        }
      }
      H[i] = hh;
      V[i] = vv;
    }
    // A line is a string: its points pull on their neighbours, so where one
    // part still coasts up while the next has turned to fall, or lands a
    // moment later, the line bends instead of splintering.
    if (lines) {
      const k = Math.min(0.45, dt * LINE_TENSION);
      const rowStart = st.rowStart;
      for (let d = 0; d < rows; d++) {
        const b = rowStart[d + 1] - 1;
        let hp = H[rowStart[d]];
        let vp = V[rowStart[d]];
        for (let i = rowStart[d] + 1; i < b; i++) {
          const hc = H[i];
          const vc = V[i];
          H[i] = hc + k * (hp + H[i + 1] - 2 * hc);
          V[i] = vc + k * (vp + V[i + 1] - 2 * vc);
          hp = hc;
          vp = vc;
        }
      }
    }
  }

  for (let i = 0; i < n; i++) {
    const X = GX[i];
    const Z = GZ[i];
    const hh = H[i];

    // Project. A dot off the sides is not drawn; a line keeps every point,
    // so it runs on unbroken to the edge.
    const kz = 1 / (1 + persp * Z);
    const sx = cw / 2 + X * kz;
    const edge = Math.abs(sx - cw / 2);
    if (!lines && edge > halfW) {
      PS[i] = -1;
      continue;
    }

    // The sheet's own shape — its arc and tails — and its ripple.
    const dzH = Z - hillZ;
    let Y = -(X * X * domeX) - dzH * dzH * domeZ + hh;
    if (tailA !== 0) {
      const u = edge * iHalf - tailStart;
      if (u > 0) {
        const q = Math.min(1, u * tailSpan);
        Y += tailA * Math.pow(q, tailCurve);
      }
    }
    if (rippleAmp > 0) {
      Y += (vnoise((X - drift) * iRx, Z * iRz + t * 0.33) - 0.5) * 2 * rippleAmp;
    }
    const sy = y0 - (Z * sinT + Y * cosT) * kz;
    if (!lines && (sy < -4 || sy > ch + 4)) {
      PS[i] = -1;
      continue;
    }

    // Near points larger and brighter; lifted ones catch the light; the
    // sheet dissolves toward the sides and the far edge.
    const near = (kz - K_FAR) / (1 - K_FAR);
    const lifted = Math.min(1, hh * liftRef);
    const side = 1 - edge / halfW;
    const fade = (sideFade > 0 ? smoothstep(0, sideFade, side) : side > 0 ? 1 : 0) * smoothstep(1, 0.7, Z / depth);
    PX[i] = sx;
    PY[i] = sy;
    PS[i] = Math.min(1, ((0.1 + 0.42 * near) * presence + 0.62 * lifted * (0.45 + 0.55 * near)) * fade);
    PR[i] = (0.28 + 0.92 * near + 0.32 * lifted) * rBase;
  }

  inkStyles(dark);
  if (lines) paintLines(st, config, sc);
  else paintDots(st, config.dotShape === 'square');
}

/** Dots: one path per shade, faint first, so the lit dots sit on top. */
function paintDots(st: SurfaceState, square: boolean): void {
  const { ctx, n, px, py, ps, pr, pb, order } = st;
  bucketCount.fill(0);
  for (let i = 0; i < n; i++) {
    const s = ps[i];
    if (s < S_MIN) continue;
    const b = bucketOf(s);
    pb[i] = b;
    bucketCount[b]++;
  }
  let at = 0;
  for (let b = 0; b < BUCKETS; b++) {
    bucketAt[b] = at;
    at += bucketCount[b];
  }
  for (let i = 0; i < n; i++) {
    if (ps[i] < S_MIN) continue;
    order[bucketAt[pb[i]]++] = i;
  }
  let from = 0;
  for (let b = 0; b < BUCKETS; b++) {
    const to = from + bucketCount[b];
    if (to === from) continue;
    ctx.beginPath();
    for (let k = from; k < to; k++) {
      const i = order[k];
      const x = px[i];
      const y = py[i];
      const r = pr[i];
      if (square) {
        const hs = r * SQUARE;
        ctx.rect(x - hs, y - hs, 2 * hs, 2 * hs);
      } else {
        ctx.moveTo(x + r, y);
        ctx.arc(x, y, r, 0, TWO_PI);
      }
    }
    ctx.fillStyle = bucketStyle[b];
    ctx.fill();
    from = to;
  }
}

/** A row's ink along its length: a horizontal gradient through its points' shades. */
function rowInk(ctx: CanvasRenderingContext2D, st: SurfaceState, a: number, b: number): CanvasGradient {
  const { px, ps } = st;
  const x0 = px[a];
  const span = px[b - 1] - x0 || 1;
  const g = ctx.createLinearGradient(x0, 0, x0 + span, 0);
  const stride = Math.max(1, Math.ceil((b - a) / LINE_STOPS));
  for (let i = a; ; i += stride) {
    if (i > b - 1) i = b - 1;
    const s = ps[i];
    g.addColorStop(Math.max(0, Math.min(1, (px[i] - x0) / span)), s < S_MIN ? clearStyle : bucketStyle[bucketOf(s)]);
    if (i === b - 1) break;
  }
  return g;
}

/**
 * Lines, back to front: each row across the sheet, the columns running into
 * the depth between it and the row behind, or both. Unless see-through,
 * each row first clears what was drawn below its line — the sheet from that
 * row forward covers it — so a raised ridge hides the lines behind it and
 * the landscape reads as solid. Every line takes its row's width (finer in
 * the distance) and a gradient through its points' shades.
 */
function paintLines(st: SurfaceState, config: VoiceDriverConfig, sc: number): void {
  const { ctx, rows, rowStart, rowFirst, colEvery, px, py, ps, gz, persp } = st;
  const drawRows = config.linePattern !== 'columns';
  const drawCols = config.linePattern !== 'rows';
  const solid = !config.seeThrough;
  const width = Math.max(0.05, config.lineWidth) * sc;
  ctx.lineJoin = 'round';
  ctx.lineCap = 'round';
  ctx.fillStyle = '#000';
  // The lowest point drawn so far: nothing lies below it to hide.
  let low = -Infinity;
  for (let d = 0; d < rows; d++) {
    const a = rowStart[d];
    const b = rowStart[d + 1];
    if (b - a < 2) continue;
    const kz = 1 / (1 + persp * gz[a]);
    const lw = width * (0.45 + 0.75 * (kz - K_FAR) / (1 - K_FAR));
    let top = Infinity;
    let bottom = -Infinity;
    let lit = false;
    for (let i = a; i < b; i++) {
      const y = py[i];
      if (y < top) top = y;
      if (y > bottom) bottom = y;
      if (ps[i] >= S_MIN) lit = true;
    }
    if (solid && top < low) {
      // The strip between this row's line and the lowest point drawn. Where
      // the line runs below that point the path folds back over empty
      // canvas, which clears nothing.
      ctx.globalCompositeOperation = 'destination-out';
      ctx.beginPath();
      ctx.moveTo(px[a], py[a]);
      for (let i = a + 1; i < b; i++) ctx.lineTo(px[i], py[i]);
      ctx.lineTo(px[b - 1], low + 1);
      ctx.lineTo(px[a], low + 1);
      ctx.closePath();
      ctx.fill();
      ctx.globalCompositeOperation = 'source-over';
    }
    if (lit) {
      ctx.strokeStyle = rowInk(ctx, st, a, b);
      ctx.lineWidth = lw;
      if (drawCols && d > 0) {
        // Each column's step from the row behind to this one: the same
        // lattice index in both (the row behind is the wider one).
        const pa = rowStart[d - 1];
        const pFirst = rowFirst[d - 1];
        const pCount = a - pa;
        const first = rowFirst[d];
        const last = first + (b - a) - 1;
        let any = false;
        ctx.beginPath();
        for (let li = Math.ceil(first / colEvery) * colEvery; li <= last; li += colEvery) {
          const jo = li - pFirst;
          if (jo < 0 || jo >= pCount) continue;
          const i = a + (li - first);
          const j = pa + jo;
          if (ps[i] < S_MIN && ps[j] < S_MIN) continue;
          // A step that climbs toward the viewer is the back of a ridge.
          if (solid && py[j] > py[i] + 0.5) continue;
          ctx.moveTo(px[j], py[j]);
          ctx.lineTo(px[i], py[i]);
          any = true;
        }
        if (any) ctx.stroke();
      }
      if (drawRows) {
        ctx.beginPath();
        ctx.moveTo(px[a], py[a]);
        for (let i = a + 1; i < b; i++) ctx.lineTo(px[i], py[i]);
        ctx.stroke();
      }
    }
    if (bottom + lw > low) low = bottom + lw;
  }
}

import type { CSSProperties, ReactNode, HTMLAttributes } from 'react';

/**
 * Host preset — retunes the glow's geometry for the element it wraps
 * - 'default': a chat input or card, ~350px wide
 * - 'pill': a small recording pill, ~150×44 — glow pulled in, shallower bend
 * - 'mobile': the bottom of a phone screen — wider range, taller rise
 *
 * A preset only supplies defaults; every geometry prop still overrides it.
 */
export type VoiceBeamType = 'default' | 'pill' | 'mobile';

/**
 * Theme mode for adapting beam colors to the background
 */
export type VoiceBeamTheme = 'dark' | 'light' | 'auto';

/**
 * How the voice is drawn
 * - 'glow': coloured light — soft gradients, a band of light along the
 *   glow's ceiling and a blurred bloom (default)
 * - 'dots': a gently domed sheet of dots seen in perspective, in the
 *   dotted language of thinking-orbs. The voice raises hills out of it —
 *   the spectrum as a landscape, drifting with the flow — and when the
 *   voice drops the dots fall back under gravity, landing with a small
 *   bounce. White on the dark theme, near-black ink on the light one; the
 *   colour props do not apply.
 * - 'lines': the same sheet drawn as lines — rows across it, columns into
 *   the depth, or a grid — solid, so a raised ridge hides the lines behind
 *   it, and falling back as smooth curves.
 *
 * Dots and lines share the surface props (`surfaceHeight`, `surfaceCurve`,
 * the `surfaceTail` set, `surfaceFade`, `texture`, `gravity`).
 */
export type VoiceBeamLook = 'glow' | 'dots' | 'lines';

/** A dot's shape, for `look="dots"`. */
export type VoiceBeamDotShape = 'round' | 'square';

/**
 * Which way the lines run, for `look="lines"`
 * - 'rows': across the surface, one line per row — a ridgeline landscape (default)
 * - 'columns': into the depth, converging with the perspective
 * - 'grid': both, a wireframe sheet
 */
export type VoiceBeamLinePattern = 'rows' | 'columns' | 'grid';

/**
 * Color variant for the beam — the same eight palettes as border-beam
 * - 'colorful': Full spectrum, Siri-like (default)
 * - 'mono': Monochromatic grayscale
 * - 'ocean': Blue and purple tones
 * - 'sunset': Warm orange, yellow, and red tones
 * - 'forest': Green and teal tones
 * - 'candy': Pink and magenta tones
 * - 'ice': Cyan and pale blue tones
 * - 'gold': Amber and yellow tones
 */
export type VoiceBeamColorVariant =
  | 'colorful'
  | 'mono'
  | 'ocean'
  | 'sunset'
  | 'forest'
  | 'candy'
  | 'ice'
  | 'gold';

/**
 * A level source: a plain number, or a getter the driver samples every
 * frame. Pass a getter for anything that changes many times a second so
 * the component does not re-render per frame.
 */
export type VoiceBeamLevel = number | (() => number);

/**
 * The glow's motion for one frame.
 * - `gather`: 0 the voice glow at rest … 1 the lobes gathered into one beam
 * - `offset`: where the beam sits, in half-widths of the lobe ring (0 = centre)
 * - `stretch`: extra width while it moves, 0–1
 * - `heldLevel`: the level the glow is held at while gathered, 0–1
 * - `cornerFollow`: how much the beam rides the element's corner arcs, 0–1
 */
export interface VoiceBeamMotion {
  gather: number;
  offset?: number;
  stretch?: number;
  heldLevel?: number;
  cornerFollow?: number;
}

/**
 * Theme color configuration
 */
export interface VoiceThemeColors {
  strokeOpacity: number;
  innerOpacity: number;
  bloomOpacity: number;
  innerShadow: string;
  saturation: number;
  brightness: number;
  /** Optional per-theme hue drift defaults; fall back to 24° / 12 s / 0°. */
  hueRange?: number;
  hueDuration?: number;
  hueBase?: number;
  /** Optional per-theme overall strength (falls back to 1). */
  strength?: number;
  /** Optional per-theme band strength for types that do not set their own. */
  bandStrength?: number;
}

/**
 * Props for the VoiceBeam component
 */
export interface VoiceBeamProps extends Omit<HTMLAttributes<HTMLDivElement>, 'children'> {
  /** Content to wrap with the voice beam effect */
  children: ReactNode;

  /**
   * Host preset: 'default' (chat input), 'pill' (recording pill) or
   * 'mobile' (bottom of a phone screen). Sets the defaults of the
   * geometry props below for that host; any prop you pass still wins.
   * @default 'default'
   */
