  breatheDuration?: number;

  /**
   * How tall the glow grows at full level, as a multiple of its resting
   * height. The rise is centered on the bottom edge.
   * @default 1.2 (1.8 on the light theme; 1.35 for `pill`, 3 for `mobile`)
